import { readFileSync } from "node:fs";
import { DEFAULT_SECRET_PREFIX, ENVIRONMENT_SETTING, WORKFLOW_DIRECTORY, } from "./constants.js";
import { ensureEnvironment } from "./github.js";
import { parseOptions } from "./options.js";
import { deps, progress, ValueError, within, } from "./runtime.js";
import { secretsPage, setupWorkflow, workflowSecrets } from "./workflowText.js";
const ENV_ASSIGNMENT = /^[ \t]*(?:export[ \t]+)?([A-Za-z_][A-Za-z0-9_]*)[ \t]*=/;
const ENV_ESCAPES = {
    n: "\n",
    r: "\r",
    t: "\t",
    '"': '"',
    "\\": "\\",
};
function readEnvironmentValue(text, assignmentEnd, name) {
    let start = assignmentEnd;
    while (start < text.length && " \t".includes(text[start])) {
        start += 1;
    }
    if (start < text.length && ["'", '"'].includes(text[start])) {
        const quote = text[start];
        const pieces = [];
        let position = start + 1;
        while (position < text.length) {
            const character = text[position];
            if (character === "\\" && quote === '"' && position + 1 < text.length) {
                const following = text[position + 1];
                pieces.push(ENV_ESCAPES[following] ?? character + following);
                position += 2;
                continue;
            }
            if (character === quote) {
                return [pieces.join(""), position + 1];
            }
            pieces.push(character);
            position += 1;
        }
        throw new ValueError(`${name} opens a quote that the file never closes`);
    }
    let end = text.indexOf("\n", assignmentEnd);
    end = end === -1 ? text.length : end;
    const raw = text.slice(assignmentEnd, end);
    const comment = /\s#/.exec(raw);
    return [(comment === null ? raw : raw.slice(0, comment.index)).trim(), end];
}
export function parseEnvironmentFile(text) {
    const values = {};
    let position = 0;
    while (position < text.length) {
        let end = text.indexOf("\n", position);
        end = end === -1 ? text.length : end;
        const line = text.slice(position, end);
        const match = ENV_ASSIGNMENT.exec(line);
        if (match === null || line.trimStart().startsWith("#")) {
            position = end + 1;
            continue;
        }
        const [value, consumed] = readEnvironmentValue(text, position + match[0].length, match[1]);
        values[match[1]] = value;
        const newline = text.indexOf("\n", consumed);
        position = newline === -1 ? text.length : newline + 1;
    }
    return values;
}
function secretValue(value) {
    if (!value.includes("\n")) {
        return value;
    }
    try {
        return JSON.stringify(JSON.parse(value));
    }
    catch {
        return value;
    }
}
export async function configureSecrets(argv) {
    const args = parseOptions({
        prog: "bitfab-replay --cloud-secrets",
        description: "Copy named values from local environment files into the GitHub Actions secrets the cloud replay workflow reads. Values are piped to the GitHub CLI on standard input and never printed, logged, or passed as arguments. Without the GitHub CLI, it lists the secrets to create by hand and where.",
        positional: {
            name: "names",
            help: "Environment variable names to copy; defaults to every secret the workflow maps",
        },
        options: [
            {
                flag: "--env-file",
                kind: "append",
                required: true,
                help: "Repository-relative environment file to read; repeatable, earliest definition wins",
            },
            {
                flag: "--environment",
                kind: "value",
                help: "GitHub Environment to set the secrets in; defaults to the workflow's environment, and is created when it does not exist",
            },
            {
                flag: "--dry-run",
                kind: "switch",
                help: "Report which names were found without writing anything to GitHub",
            },
        ],
    }, argv);
    const root = deps.rootDirectory();
    const text = readFileSync(within(root, `${WORKFLOW_DIRECTORY}/${setupWorkflow(root)}`), "utf8");
    const targets = workflowSecrets(text);
    const names = args.names.length > 0 ? args.names : Object.keys(targets);
    const unknown = names.filter((name) => !(name in targets));
    if (unknown.length > 0) {
        throw new ValueError(`The workflow does not read ${unknown.join(", ")}. Add each one to the replay step's env as NAME: \${{ secrets.${DEFAULT_SECRET_PREFIX}NAME }} first`);
    }
    const configured = ENVIRONMENT_SETTING.exec(text);
    const environment = args.environment || (configured ? configured[1] : null);
    const values = {};
    for (const file of args.env_file) {
        for (const [key, value] of Object.entries(parseEnvironmentFile(readFileSync(within(root, file), "utf8")))) {
            if (!(key in values)) {
                values[key] = value;
            }
        }
    }
    const repo = deps.repository(root);
    const found = [];
    const missing = [];
    const empty = [];
    const lookupValue = (name) => name in values ? values[name] : values[targets[name]];
    for (const name of names) {
        const value = lookupValue(name);
        if (value === undefined) {
            missing.push(targets[name]);
        }
        else if (!value) {
            empty.push(targets[name]);
        }
        else {
            found.push(name);
        }
    }
    const result = {
        repository: repo,
        environment,
        dryRun: args.dry_run,
        set: [],
        missing,
        empty,
    };
    if (args.dry_run) {
        return { ...result, wouldSet: found.map((name) => targets[name]) };
    }
    if (environment) {
        result.environmentStatus = await ensureEnvironment(repo, environment);
    }
    if (found.length > 0 && deps.which("gh") === null) {
        progress("Setting secrets needs the GitHub CLI (https://cli.github.com), which encrypts each value for GitHub; create the ones listed under createByHand instead");
        return {
            ...result,
            createByHand: found.map((name) => targets[name]),
            where: secretsPage(repo, environment),
        };
    }
    const token = deps.githubAccess().token;
    for (const name of found) {
        deps.command([
            "gh",
            "secret",
            "set",
            targets[name],
            "--repo",
            repo,
            ...(environment ? ["--env", environment] : []),
        ], {
            input: secretValue(lookupValue(name)),
            env: { ...process.env, GH_TOKEN: token },
        });
    }
    result.set = found.map((name) => targets[name]);
    if (missing.length > 0 || empty.length > 0) {
        result.where = secretsPage(repo, environment);
    }
    return result;
}
